from typing import List

class GridTree:
    def __init__(self, grid):
        self.grid = grid
        self.n = len(grid[0])
        self.m = len(grid)
        self.tree = defaultdict(int)

    def find(self, x):
        if self.tree[x] == x:
            return x
        self.tree[x] = self.find(self.tree[x])
        return self.tree[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.tree[root_y] = root_x

    def count(self):
        return len(self.tree)

    def calculate(self, x1, y1, x2, y2):
        x1, y1 = self.find(x1), self.find(y1)
        x2, y2 = self.find(x2), self.find(y2)
        left_max = x1
        top_max = y1
        right_min = x2
        bottom_min = y2
        count = 0
        for i in range(left_max, right_min + 1):
            for j in range(top_max, bottom_min + 1):
                if grid[j][i] == 0: 
                    count += self.tree[1]
                else:  
                    count += grid[j][i]
            count += sum(grid[j])
