def build_graph(n, m, relations):
    graph = defaultdict(list)
    time = [float('inf')] * (n * m)
    start_time = float('inf')

    for r in relations:
        i, j, w = r
        time[i * m + j] = min(time[i * m + j], start_time)
        start_time = w

    for i in range(n):
        for j in range(m):
            if time[i * m + j] < start_time:
                continue
            for d in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
                x, y = i + d[0], j + d[1]
                if x >= 0 and x < n and y >= 0 and y < m:
                    graph[i * m + j].append((x * m + y, time[i * m + j]))

    return graph, time

def dijkstra(n, m, graph, time):
    dist = [float('inf')] * (n * m)
    visited = [False] * (n * m)
    pq = [(0, 0, 0)]

    while pq:
        cost, i, j = heappop(pq)

        if visited[i * m + j]:
            continue
        visited[i * m + j] = True

        for x, w in graph[i * m + j]:
            if dist[x] > w + cost:
                dist[x] = w + cost
                heappush(pq, (w + cost, x, j))

    return [dist[i * m + j] for i in range(n) for j in range(m) if not visited[i * m + j]]

def on_or_off(garland, i, new_state):
    heap = [(garland[i], 0)] if new_state else []
    while heap:
        state, i = heappop(heap)
        garland[i] = new_state

        for d in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            x, y = i[0] + d[0], i[1] + d[1]
