def find_longest_subarray(array):
    frequency, max_frequency, result = {}, 0, 0

    for num in array:
        if num not in frequency:
            frequency[num] = 1
        else:
            frequency[num] += 1

        current_frequency = frequency[num]
        if current_frequency > max_frequency:
            max_frequency = current_frequency

        if max_frequency >= 2:
            if frequency[num] == max_frequency:
                result = max(result, current_frequency + frequency[num] + 1)
            else:
                result = max(result, current_frequency + 1)

