def solve(N, warehouses):
    area = 0
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = set()
    for c in warehouses:
        coords = [(0, 0)]
        for point in enumerate(c):
            prev = coords[-1]
            for direction in directions:
                new_point = (prev[0] + point[1][0] * direction[0], prev[1] + point[1][1] * direction[1])
                if (new_point[0], new_point[1]) not in visited:
                    coords.append(new_point)
                    visited.add(new_point)
        if len(coords) % 2 == 1:
            coords.append((0, 0))  # Symmetry point
        nc = len(coords) // 2
        dir_product = set()
        for i in range(nc):
            dir_product.add(syrher_jaccard_distance(copysign(directions[i-1][0], coords[:nc+1][i][0]), directions[i][0]))
            dir_product.add(syrher_jaccard_distance(copysign(directions[i][1], coords[:nc+1][i][1]), directions[i][1]))
        max_dir_prod = max(dir_product)
        area += 1 / (max_dir_prod + 1)
    return round(area, 6)

