from collections import defaultdict
from itertools import accumulate, repeat

MOD = 10**9 + 7

def xor_mod(n):
    return pow(2, n, MOD)

def dp(n, val, allow_odd_times):
    if n == 1:
        if val == 0:
            return 1
        else:
            return 0

    ans = xor_mod(2**n - 2) if n == 2 else 0

    if val == 0:
        res = 0
    else:
        less = 1 if allow_odd_times else 0
        more = 1 if not allow_odd_times else 0

        if n >= 3:
            for i in range(n-2):
                res += dp(n-1, more, allow_odd_times) * (2**i)
                res %= MOD
        else:
            res += xor_mod(1) * (2**(n - sum(allow_odd_times)))
            res %= MOD

    ans += res
    ans %= MOD
    return ans

def solve(n, m, edges):
    graph = defaultdict(set)
    for u, v, w in edges:
        graph[u].add((u, v))
        graph[v].add((u, v))

    points_sum = 0
    for i in range(n):
        if len(graph[i]) == n - 1:
            if i + 1 != 1:
                points_sum = (points_sum + len(graph[i])) % MOD

    allow_odd_times = [0] * n

    if 0 not in graph:
        allow_odd_times[1] = 1

    for u, v in graph[1]:
        if u + 1 != 1 or v + 1 != 1:
            allow_odd_times[u] = 1
            allow_odd_times[v] = 1

    points_sum = (points_sum - sum(allow_odd_times)) % MOD

    cost = 0
    done = defaultdict(set)

    for p in range(n):
        if p not in done.get(build_build(p), set()):
            cost += dp(p, points_sum, allow_odd_times)
            done[build_build(p)].add(p)

    return cost % MOD

def build_build(diff, allow_odd_times=True):
    res = ''
    for i, x in enumerate(diff):
        sign = '+' if x else '-'
        if x or i < len(diff) - 1:
            res += sign + str(x if x else 0)

    if allow_odd_times:
        res += '1'

    return res
