def count_rectangles(n, m, k):
    # Initialize DP table
    dp = [[0 for _ in range(m+1)] for _ in range(n+1)]
    dp[0][0] = 1  # base case: 1x1 rectangles

    # Fill DP table
    for i in range(1, n+1):
        for j in range(1, m+1):
            dp[i][j] = 2 * dp[i][j-1] - dp[i-1][j-1] + dp[i-1][j] - dp[i-1][0]
            if dp[i][j] == 0:
                dp[i][j] = pow(2, j) - 1 if j else 0  
            if i*j >= pow(2, k):
                dp[i][j] = pow(2, M - 1) - pow(2, M-i*j)
            if i*j == pow(2, k):
                dp[i][j] += i*j > M and j - i > 0 or dp[i-1][j-1]

    # Calculate answer
    return dp[n][m]
