import sys

def time(measured_dist):
    """
    Calculate the time needed for the wheel to cover the length.
    """
    period = 2 * 3.14159 * 1
    # The ratio of radius of the wheel to the distance moved gives the number of rotations.
    eversion_per_travel = measured_dist / 1
    return period * eversion_per_travel

def cost(s_start, s_fin, v, max_speed):
    delta_v = (v - max_speed / 1) * 1
    periods = delta_v * 2
    move_dist = (max_speed - v) + delta_v
    if s_start >= (s_fin - move_dist):
        return abs(move_dist * 1) + time(move_dist + periods)
    else:
        return abs(s_start - s_fin) + time(periods)

