from collections import defaultdict

def toposort(graph, in_degree):
    queue = [node for node in graph if in_degree[node] == 0]
    sorted_nodes = []
    while queue:
        node = queue.pop(0)
        sorted_nodes.append(node)
        for neighbour in graph[node]:
            in_degree[neighbour] -= 1
            if in_degree[neighbour] == 0:
                queue.append(neighbour)
    return sorted_nodes if len(sorted_nodes) == len(graph) else []

def find_vision_paths(graph, in_degree, start_node):
    sorted_nodes = toposort(graph, in_degree)
    correct_paths = defaultdict(int)
    for i in range(len(sorted_nodes)):
        for j in range(i + 1, len(sorted_nodes)):
            pass_node = sorted_nodes[i]
            visit_node = sorted_nodes[j]
            if visit_node in graph[pass_node]:
                valid_path = True
                valid_path_length = 0
                path_length = 0
                current_node = pass_node
                vision_index = 0
                while current_node in graph and valid_path:
                    if vision_index < len(graph[current_node]):
                        seen_vision = graph[current_node][vision_index]
                        if seen_vision == visit_node:
                            valid_path_length += 1
                            vision_index += 1
                        elif valid_path_length > 0:
                            if path_length > 0:
                                correct_paths[path_length] += 1
                            path_length = 0
                            (cur_visit, direction) = visit_node
                            correct_paths[path_length + valid_path_length] += 1
                            (current_node = pass_node, valid_path = False)
                    current_node = graph[current_node][1]
                    path_length += 1
                if valid_path and path_length > 0:
                    correct_paths[path_length] += 1
    return list(correct_paths.keys())

def main():
