from collections import deque

def change_bead(n, a, l, r, x):
    a[l-1] = x
    return a

def query_memory(n, a, l, r):
    return sum(i-l+1 for i in range(l, r+1) if a[i-1] != -1)

def solve_queries(n, a, queries):
    for op, l, r in queries:
        if op == 1:
            a = change_bead(n, a, l-1, r-1, a[l-1])
        else:
            print(query_memory(n, a, l-1, r-1))

