                continue
            else:
                largest_freq_value_index = most_frequent[num][1]
        else:
            largest_freq_value_index = 0

        if current_freq == arr[start_index[largest_freq_value_index]+1:] and len(length_dict[num]) == 3 and frequency[num] == length_dict[num][0] + len(arr[start_index[largest_freq_value_index]+1:]):
            start_index[num] = most_frequent[num][1] + 1
            longest_subarray = max(longest_subarray, most_frequent[num][1] - start_index[num] + 1)

        if frequency[num] > max_frequency:
            max_frequency = frequency[num]
            start_index = [max_frequency + 1]
            length_dict[num] = [len(arr), length_dict[num][1], frequency[num]]

        if frequency[num] == max_frequency and len(length_dict[num]) < 1:
            length_dict[num] = [1, frequency[num], frequency[num]]

        if i > max_frequency and frequency[num] == max_frequency:
            most_frequent[num] = (length_dict[num][1], frequency[num]+1)
            length_dict[num][0] += 1
        elif i + 1 - start_index[length_dict[num][0]] == len(arr) and len(length_dict[num]) > 2:
            start_index[length_dict[num][1]] = max_frequency + 1
            length_dict[num] = [len(arr)+1, frequency[num]+1, frequency[num]-1]
            max_frequency = frequency[num] - 1

        if frequency[num] > length_dict[num][2]:
            length_dict[num][2] = frequency[num]
            most_frequent[num] = [i+1, length_dict[num][1], frequency[num]]

    if max_frequency == 1:
        return 0
